import os
import requests


FIREBASE_API_KEY = os.environ["FIREBASE_WEB_API_KEY"]
FIREBASE_SIGN_IN_URL = (
    f"https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key={FIREBASE_API_KEY}"
)


class FirebaseAuthError(Exception):
    pass


def sign_in_with_email_password(email: str, password: str) -> dict:
    resp = requests.post(
        FIREBASE_SIGN_IN_URL,
        json={
            "email": email,
            "password": password,
            "returnSecureToken": True,
        },
        timeout=30,
    )

    try:
        data = resp.json()
    except ValueError as e:
        raise FirebaseAuthError("Invalid JSON response from Firebase Auth") from e

    if not resp.ok:
        message = data.get("error", {}).get("message", "Authentication failed")
        raise FirebaseAuthError(message)

    return {
        "id_token": data["idToken"],
        "refresh_token": data["refreshToken"],
        "access_token": data["idToken"],
        "expires_in": int(data["expiresIn"]),
        "local_id": data["localId"],
        "email": data.get("email", email),
    }
